_Static_assert(sizeof(pg_resource_candidate)==32&&sizeof(pg_resource_host)==24&&sizeof(pg_resources)==64,"resources ABI");
_Static_assert(sizeof(pg_resource_ops)==40&&offsetof(pg_resource_ops,expand)==32,"resource ops ABI");
typedef struct {pg_resources resources;json_object *configuration;unsigned calls,busy,mode,reenter;} fixture;
static fixture *current;
int __real_json_object_object_add(json_object *,const char *,json_object *);
int __wrap_json_object_object_add(json_object *object,const char *key,json_object *value){if(current&&current->mode==3&&object==current->configuration&&!strcmp(key,"systemPrompt"))return -1;return __real_json_object_object_add(object,key,value);}
static int busy(void *context){return (int)((fixture *)context)->busy;}
static int build(void *context,pg_resource_candidate *out){fixture *f=context;f->calls++;if(f->reenter)assert(pg_resources_reload(&f->resources)==3);out->skills=json_tokener_parse("{\"skills\":[],\"diagnostics\":[]}");out->templates=json_tokener_parse("{\"templates\":[{\"name\":\"recipe\",\"body\":\"Recipe $1\"}],\"diagnostics\":[]}");out->settings=json_tokener_parse("{\"global\":{\"private\":\"PRIVATE_SETTING_VALUE\"},\"diagnostics\":[{\"message\":\"warning\"}]}");out->prompt=json_object_new_string(f->calls==1?"PanGu first":"PanGu refreshed");assert(out->skills&&out->templates&&out->settings&&out->prompt);if(f->mode==1)return 5;if(f->mode==2)assert(!json_object_object_add(out->templates,"templates",json_object_new_object()));return 0;}
static json_object *snapshot(fixture *f,unsigned revision){json_object *value=0;assert(!pg_resources_snapshot(&f->resources,&value)&&value);assert(json_object_get_uint64(json_object_object_get(value,"revision"))==revision);assert(!strstr(json_object_to_json_string_ext(value,JSON_C_TO_STRING_PLAIN),"PRIVATE_SETTING_VALUE"));assert(json_object_array_length(json_object_object_get(value,"diagnostics"))==1);return value;}
int main(void){fixture f={0};current=&f;f.configuration=json_object_new_object();assert(f.configuration);pg_resource_host host={&f,build,busy};assert(!pg_resources_open(&f.resources,&host,f.configuration)&&f.resources.revision==1);json_object *value=snapshot(&f,1);json_object *templates=json_object_object_get(json_object_object_get(value,"templates"),"templates");assert(!json_object_object_add(json_object_array_get_idx(templates,0),"body",json_object_new_string("Corrupt snapshot")));json_object_put(value);char output[256];size_t size=0;assert(!pg_resources_expand(&f.resources,(pg_slice){"/recipe value",13},output,sizeof(output),&size)&&!strcmp(output,"Recipe value"));f.busy=1;unsigned calls=f.calls;assert(pg_resources_reload(&f.resources)==3&&f.calls==calls);f.busy=0;f.reenter=1;assert(!pg_resources_reload(&f.resources)&&f.resources.revision==2);f.reenter=0;assert(!strcmp(json_object_get_string(json_object_object_get(f.configuration,"systemPrompt")),"PanGu refreshed"));
 for(unsigned mode=1;mode<=3;mode++){f.mode=mode;assert(pg_resources_reload(&f.resources)==5&&f.resources.revision==2);assert(!strcmp(json_object_get_string(json_object_object_get(f.configuration,"systemPrompt")),"PanGu refreshed"));value=snapshot(&f,2);json_object_put(value);assert(!pg_resources_expand(&f.resources,(pg_slice){"/recipe value",13},output,sizeof(output),&size)&&!strcmp(output,"Recipe value"));}f.mode=0;assert(!pg_resources_close(&f.resources));assert(pg_resources_reload(&f.resources)==7);value=(void *)1;assert(pg_resources_snapshot(&f.resources,&value)==7&&!value);size=99;assert(pg_resources_expand(&f.resources,(pg_slice){"text",4},output,sizeof(output),&size)==7&&!size&&!output[0]);assert(!pg_resources_close(&f.resources));json_object_put(f.configuration);puts("PASS: atomic resource refresh, detached snapshots, busy/reentry, failed candidate/publication retention and close");}
